const C=window.NAVA_CONFIG||{};const sup=window.supabase;let sb=null,current='home',ringtones=[],pending={};const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
if(C.SUPABASE_URL&&C.SUPABASE_ANON_KEY&&sup)sb=sup.createClient(C.SUPABASE_URL,C.SUPABASE_ANON_KEY);function toast(m){const x=$('#toast');x.textContent=m;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),3200)}async function api(fn,body={}){if(!C.SUPABASE_URL||!C.SUPABASE_ANON_KEY)throw Error('Supabase is not configured in config.js');const r=await fetch(C.SUPABASE_URL+'/functions/v1/'+fn,{method:'POST',headers:{'Content-Type':'application/json','apikey':C.SUPABASE_ANON_KEY,'Authorization':'Bearer '+C.SUPABASE_ANON_KEY},body:JSON.stringify(body)});let j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.error||'Request failed');return j}
const pages=[['home','🏠 Home'],['solve','🧠 AI Solve'],['music-generator','🎼 Music Generator'],['ringtone-generator','🎵 Ringtone Generator'],['ringtone-library','📚 Ringtone Library'],['search','🔎 NavaBharat Search'],['science','🔬 Science'],['translator','🌐 Translator'],['live','📡 Live Tools'],['current-affairs','🗞️ Current Affairs'],['jobs','💼 Jobs & Exams'],['music-library','🎧 RacharlaGPT Music'],['admin','🔐 Admin'],['video','🎬 Video Studio'],['creator','✨ Creator Studio'],['design','🎨 Design Studio'],['premium','💎 Premium & Support'],['about','ℹ️ About'],['privacy','🔒 Privacy'],['contact','✉️ Contact']];$('#nav').innerHTML=pages.map(x=>`<button data-page="${x[0]}">${x[1]}</button>`).join('');document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#menu').onclick=()=>$('#sidebar').classList.add('open');$('#closeNav').onclick=()=>$('#sidebar').classList.remove('open');$('#theme').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('nava-theme',document.body.classList.contains('light')?'light':'dark')};if(localStorage.getItem('nava-theme')==='light')document.body.classList.add('light');
function go(p){current=p;history.replaceState({},'',p==='home'?'/':'/?page='+p);document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#crumb').textContent=pages.find(x=>x[0]===p)?.[1]||'NavaBharat AI';$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function share(text,url=location.href){const t=encodeURIComponent(text),u=encodeURIComponent(url);return `<div class="share-grid"><a target="_blank" href="https://wa.me/?text=${t}%20${u}">WhatsApp</a><a target="_blank" href="https://t.me/share/url?url=${u}&text=${t}">Telegram</a><a target="_blank" href="https://www.facebook.com/sharer/sharer.php?u=${u}">Facebook</a><a target="_blank" href="https://twitter.com/intent/tweet?text=${t}&url=${u}">X</a><a target="_blank" href="https://www.instagram.com/">Instagram</a></div>`}
function home(){return `<section class="hero"><h1>India's glossy AI workspace.</h1><p>NavaBharat AI is a product of RacharlaGPT. Create original songs and ringtones, explore a rights-aware ringtone catalog, solve questions, translate, search, make designs and publish creator content — from one mobile/desktop-friendly app.</p><div class="row"><button class="btn" onclick="go('music-generator')">🎼 Create a Song</button><button class="btn secondary" onclick="go('ringtone-generator')">🎵 Make a Ringtone</button><button class="btn secondary" onclick="go('design')">🎨 Design</button></div></section><div class="grid">${[['solve','🧠 AI Solve','Answers, explanations and study help.'],['music-generator','🎼 Music Generator','Lyrics + idea → original AI song. Preview free; download ₹19.'],['ringtone-generator','🎵 Ringtone Generator','Customer idea/lyrics → original ringtone. Preview free; ₹10 offer.'],['ringtone-library','📚 Ringtone Library','Search and preview a rights-cleared catalog; ₹10 offer download.'],['search','🔎 NavaBharat Search','Google search plus shareable result cards.'],['design','🎨 Design Studio','Premium posters, 3D text and HD export options.'],['creator','✨ Creator Studio','YouTube, Instagram, LinkedIn and X content.'],['premium','💎 Premium & Support','Razorpay support, personalised orders and recovery.']].map(x=>`<div class="card"><h3>${x[1]}</h3><p class="muted">${x[2]}</p><button class="btn secondary" onclick="go('${x[0]}')">Open</button></div>`).join('')}</div>`}
function aiPage(title,placeholder,button,promptType){return `<section class="hero"><h1>${title}</h1><p>Powered through Supabase Edge Functions. Your provider keys stay server-side.</p></section><div class="card" style="margin-top:18px"><textarea id="aiInput" class="field" placeholder="${placeholder}"></textarea><div class="row" style="margin-top:12px"><select id="aiLang" class="field" style="max-width:220px"><option>English</option><option>Telugu</option><option>Hindi</option><option>Tamil</option><option>Kannada</option><option>Malayalam</option></select><button class="btn" onclick="runAI('${promptType}')">${button}</button></div><div id="aiOut" style="margin-top:18px"></div></div>`}
async function runAI(type){const input=$('#aiInput').value.trim(),lang=$('#aiLang').value;if(!input)return toast('Enter your request first.');$('#aiOut').innerHTML='<div class="notice">Generating…</div>';try{const j=await api('ai-text',{type,input,language:lang});$('#aiOut').innerHTML=`<pre class="output">${esc(j.text||'No answer')}</pre>${share('NavaBharat AI: '+input)}`;gtag?.('event','ai_tool',{tool:type})}catch(e){$('#aiOut').innerHTML=`<div class="notice">${esc(e.message)}</div>`}}
function solve(){return aiPage('🧠 AI Solve','Ask a maths, science, coding, reasoning or general question…','Solve','solve')}function science(){return aiPage('🔬 Science Lab','Explain a science topic, experiment or concept…','Explain','science')}function translator(){return aiPage('🌐 Translator','Paste text and choose the output language…','Translate','translate')}function live(){return `<section class="hero"><h1>📡 Live Information & Google News RSS</h1><p>Current-information tools plus live Google News RSS feeds, matching the original Live Information workflow.</p></section><div class="grid"><div class="card"><h3>🌦️ Weather</h3><button class="btn" onclick="window.open('https://www.google.com/search?q=weather','_blank')">Open Weather</button></div><div class="card"><h3>🕐 World Time</h3><button class="btn" onclick="window.open('https://www.google.com/search?q=current+time','_blank')">Check Time</button></div><div class="card"><h3>📰 Live News RSS</h3><select id="liveLang" class="field"><option>English</option><option>Telugu</option><option>Hindi</option><option>Tamil</option><option>Kannada</option><option>Malayalam</option></select><input id="liveQ" class="field" placeholder="Optional topic"><button class="btn" onclick="loadLiveRSS()">🔄 Fetch Latest RSS News</button><div id="liveRSS" style="margin-top:14px"></div></div></div>`}async function loadLiveRSS(){const q=$('#liveQ').value.trim();$('#liveRSS').innerHTML='<div class="notice">Fetching live news…</div>';try{const j=await api('live-rss',{query:q,language:$('#liveLang').value,limit:12});$('#liveRSS').innerHTML=(j.items||[]).map(x=>`<div class="card"><h4><a target="_blank" rel="noopener" href="${esc(x.link)}">${esc(x.title)}</a></h4><small>${esc(x.source||'Google News')} · ${esc(x.pubDate||'')}</small></div>`).join('')||'<p class="muted">No live items found.</p>'}catch(e){$('#liveRSS').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}
function search(){return `<section class="hero"><h1>🔎 NavaBharat Search</h1><p>Google search, AI-grounded summary, live news results, mind map, notes, infographic and share-ready posting images.</p></section><div class="card"><div class="row"><input id="q" class="field" placeholder="Search anything" style="flex:1"><button class="btn" onclick="doSearch()">Search Google</button><button class="btn secondary" onclick="groundSearch()">🤖 AI Summary</button></div><div id="searchShare" style="margin-top:18px"></div><div id="searchAI" style="margin-top:18px"></div></div>`}function doSearch(){const q=$('#q').value.trim();if(!q)return toast('Type something to search first.');window.open('https://www.google.com/search?q='+encodeURIComponent(q),'_blank');$('#searchShare').innerHTML='<h3>Share search</h3>'+share('NavaBharat AI search: '+q)}async function groundSearch(){const q=$('#q').value.trim();if(!q)return toast('Type something to search first.');$('#searchAI').innerHTML='<div class="notice">Searching and preparing AI summary…</div>';try{const [j,r]=await Promise.all([api('ai-text',{type:'search',input:q,language:'English'}),api('live-rss',{query:q,language:'English',limit:8}).catch(()=>({items:[]}))]);const ans=j.text||'No AI summary available.';const items=r.items||[];$('#searchAI').innerHTML=`<div class="card"><h3>⚡ Quick Answer</h3><pre class="output">${esc(ans)}</pre>${share('NavaBharat AI search: '+q)}</div><div class="row"><button class="btn secondary" onclick="makeSearchImage('mindmap')">🗺️ Mind Map Image</button><button class="btn secondary" onclick="makeSearchImage('notes')">📝 Notes Image</button><button class="btn secondary" onclick="makeSearchImage('infographic')">📊 Infographic</button></div><div class="grid" style="margin-top:14px"><div class="card"><h3>📰 Live Results</h3>${items.length?items.map(x=>`<p><a target="_blank" rel="noopener" href="${esc(x.link)}">${esc(x.title)}</a><br><small>${esc(x.source||'Google News')} · ${esc(x.pubDate||'')}</small></p>`).join(''):'<p class="muted">No live RSS results returned.</p>'}</div><div id="searchVisual" class="card"><p class="muted">Create a visual from this answer.</p></div></div>`;window.__searchState={q,ans,items}}catch(e){$('#searchAI').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}function makeSearchImage(kind){const st=window.__searchState;if(!st)return;const c=document.createElement('canvas');c.width=kind==='notes'?1200:1600;c.height=kind==='notes'?1500:1000;const x=c.getContext('2d');const g=x.createLinearGradient(0,0,c.width,c.height);g.addColorStop(0,'#ff9a00');g.addColorStop(.45,'#ff2d7d');g.addColorStop(1,'#5427d8');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.fillStyle='rgba(8,8,25,.55)';x.fillRect(50,50,c.width-100,c.height-100);x.fillStyle='#fff';x.textAlign='left';x.font='900 54px Arial';x.fillText(kind==='mindmap'?'NavaBharat Mind Map':kind==='notes'?'NavaBharat Quick Notes':'NavaBharat Infographic',90,130);x.font='700 38px Arial';wrapCanvas(x,st.q,90,205,c.width-180,55);x.font='28px Arial';wrapCanvas(x,st.ans,90,310,c.width-180,42);const url=c.toDataURL('image/png');$('#searchVisual').innerHTML=`<img style="width:100%;border-radius:18px" src="${url}"><a class="btn" download="navabharat-${kind}.png" href="${url}">⬇ Download PNG</a>${share('NavaBharat '+kind+': '+st.q)}`}
function musicGenerator(){return `<section class="hero"><h1>🎼 RacharlaGPT Music Generator</h1><p>Original songs with vocals/instruments. Your old generator's ACE-Step → Gemini Lyria → APIFrame failover is moved to Supabase.</p></section><div class="card" style="margin-top:18px"><div class="grid"><div><label>Song idea / lyrics</label><textarea id="songLyrics" class="field" placeholder="Write lyrics or describe the song. Example: Telugu motivational song about never giving up."></textarea></div><div><label>Style</label><select id="songStyle" class="field"><option>Tollywood Mass Folk / High Beat</option><option>Bollywood Romantic / Melodic</option><option>Lo-Fi Chill & Acoustic</option><option>EDM / Cyberpunk Synthwave</option><option>Cinematic Orchestral Epic</option><option>Hip Hop / Indian Rap</option><option>Devotional / Bhakti Fusion</option><option>Classical Fusion & Sitar</option></select><label>Language</label><select id="songLang" class="field"><option>Telugu</option><option>Hindi</option><option>English</option><option>Tamil</option><option>Kannada</option><option>Malayalam</option></select><label>Duration</label><select id="songDur" class="field"><option value="15">15 sec</option><option value="30">30 sec</option><option value="45">45 sec</option><option value="60" selected>60 sec</option></select><label>Vocals</label><select id="songVocal" class="field"><option>Solo Male Vocalist</option><option>Solo Female Vocalist</option><option>Male & Female Chorus Duet</option><option>Instrumental</option></select></div></div><div class="row" style="margin-top:14px"><button class="btn secondary" onclick="writeLyrics()">✍️ Generate Original Lyrics</button><button class="btn" onclick="generateMedia('song')">🎼 Generate Song</button></div><div id="songOut" style="margin-top:18px"></div></div>`}
async function writeLyrics(){const v=$('#songLyrics').value.trim();if(!v)return toast('Enter a topic/idea first.');try{const j=await api('ai-text',{type:'lyrics',input:v,language:$('#songLang').value});$('#songLyrics').value=j.text||'';toast('Original lyrics generated.')}catch(e){toast(e.message)}}
async function generateMedia(kind){const lyrics=kind==='song'?$('#songLyrics').value.trim():$('#ringLyrics').value.trim(),lang=kind==='song'?$('#songLang').value:$('#ringLang').value,style=kind==='song'?$('#songStyle').value:$('#ringStyle').value,duration=kind==='song'?Number($('#songDur').value):Number($('#ringDur').value);if(!lyrics)return toast('Enter lyrics or an idea.');const out=$(kind==='song'?'#songOut':'#ringOut');out.innerHTML='<div class="notice">AI providers are generating your audio… preview is free.</div>';try{const j=await api('generate-media',{kind,lyrics,language:lang,style,duration,vocal_type:kind==='song'?$('#songVocal').value:'Instrumental'});out.innerHTML=`<div class="card"><span class="pill">${esc(j.provider||'AI')}</span><h3>Preview</h3><audio class="audio" controls src="${esc(j.preview_url)}"></audio><p class="muted">${kind==='ringtone'?'Offer ₹10 (regular ₹20).':'Full download ₹19.'}</p><button class="btn" onclick="payAsset('${esc(j.asset_id)}','${kind}')">⬇ Download</button>${share('I created this with NavaBharat AI')}</div>`;pending.asset_id=j.asset_id;pending.kind=kind}catch(e){out.innerHTML=`<div class="notice">${esc(e.message)}</div>`}}
function ringtoneGenerator(){return `<section class="hero"><h1>🎵 Ringtone Generator</h1><p>Customer gives an idea or lyrics → original ringtone generation → free preview → ₹10 offer download.</p></section><div class="card" style="margin-top:18px"><textarea id="ringLyrics" class="field" placeholder="Example: 20-second energetic Telugu folk ringtone for a family celebration…"></textarea><div class="grid"><select id="ringLang" class="field"><option>Telugu</option><option>Hindi</option><option>English</option><option>Tamil</option><option>Kannada</option><option>Malayalam</option></select><select id="ringStyle" class="field"><option>Indian Folk</option><option>Devotional</option><option>Cinematic</option><option>EDM</option><option>Lo-Fi</option><option>Classical Fusion</option></select><select id="ringDur" class="field"><option value="10">10 sec</option><option value="15" selected>15 sec</option><option value="20">20 sec</option><option value="30">30 sec</option></select></div><div class="row" style="margin-top:14px"><button class="btn secondary" onclick="writeRingtoneIdea()">✨ Improve Idea</button><button class="btn" onclick="generateMedia('ringtone')">🎵 Generate Preview</button></div><div id="ringOut" style="margin-top:18px"></div></div>`}async function writeRingtoneIdea(){const v=$('#ringLyrics').value.trim();if(!v)return;try{const j=await api('ai-text',{type:'ringtone_idea',input:v,language:$('#ringLang').value});$('#ringLyrics').value=j.text}catch(e){toast(e.message)}}
async function payAsset(id,kind){try{const j=await api('create-payment',{kind,asset_id:id,amount:kind==='ringtone'?10:19});pending.order_id=j.order_id;location.href=j.payment_link;const out=document.querySelector(kind==='ringtone'?'#ringOut':'#songOut');out.insertAdjacentHTML('beforeend',`<div class="notice" id="orderBox" style="margin-top:12px">Order <b>${esc(j.order_id)}</b>. After Razorpay payment return here and click <button class="btn" onclick="verifyOrder()">Check payment & download</button>.</div>`)}catch(e){toast(e.message)}}async function verifyOrder(){try{const oid=pending.order_id||new URLSearchParams(location.search).get('order_id')||$('#recover')?.value.trim();if(!oid)throw Error('Enter or recover the Order ID');const j=await api('verify-payment',{order_id:oid});if(!j.paid)return toast('Payment not confirmed yet.');const d=await api('create-download',{order_id:oid});location.href=d.download_url}catch(e){toast(e.message)}}
async function ringtoneLibrary(){if(sb){const {data}=await sb.from('ringtones').select('*').eq('active',true).order('created_at',{ascending:false});ringtones=data||[]}return `<section class="hero"><h1>📚 Ringtone Library</h1><p>Movie/devotional/language categories are supported when the source is authorized or redistributable. Preview free; regular ₹20, launch offer ₹10.</p></section><div class="card" style="margin-top:18px"><input id="rtQ" class="field" placeholder="Search Telugu, Hindi, devotional, folk, English, Hollywood, Tollywood…" oninput="filterRT()"><div class="filters"><button onclick="setRT('All')">All</button><button onclick="setRT('Telugu')">Telugu</button><button onclick="setRT('Hindi')">Hindi</button><button onclick="setRT('English')">English</button><button onclick="setRT('Devotional')">Devotional</button><button onclick="setRT('Latest')">Latest</button><button onclick="setRT('Folk')">Folk</button></div><div id="rtGrid" class="grid">${ringtones.length?ringtones.map(rtCard).join(''):'<div class="notice">No catalog loaded yet. Run the authorized catalog importer from Supabase.</div>'}</div></div><div class="notice" style="margin-top:18px">⚖️ Commercial movie recordings cannot be copied/rehosted without redistribution rights. The importer is designed for licensed feeds, CC/public-domain sources and your own uploads. The app can still organize all languages/categories once lawful sources are connected.</div>`}let rtF='All';function setRT(f){rtF=f;filterRT()}function filterRT(){const q=($('#rtQ')?.value||'').toLowerCase();const a=ringtones.filter(x=>{const h=[x.title,x.movie,x.artist,x.language,x.category,x.tags].join(' ').toLowerCase();return(!q||h.includes(q))&&(rtF==='All'||x.language===rtF||x.category===rtF||rtF==='Latest')});$('#rtGrid').innerHTML=a.length?a.map(rtCard).join(''):'<div class="notice">No matches.</div>'}function rtCard(x){return `<div class="card"><div class="row"><span class="pill">${esc(x.language)}</span><span class="pill">${esc(x.category)}</span></div><h3>${esc(x.title)}</h3><p class="muted">${esc(x.movie||x.artist||'Authorized / public-domain source')}</p><button class="btn secondary" onclick="previewRT('${x.id}',this)">▶ Free Preview</button><audio class="audio" style="display:none" controls></audio><div class="row"><span class="price">₹${Number(x.price_inr||10)}</span><button class="btn" onclick="buyRT('${x.id}')">⬇ Download</button></div></div>`}async function previewRT(id,b){try{const j=await api('preview-ringtone',{item_id:id});const a=b.parentElement.querySelector('audio');a.src=j.preview_url;a.style.display='block';a.play()}catch(e){toast(e.message)}}async function buyRT(id){try{const item=ringtones.find(x=>String(x.id)===String(id));const amount=Math.max(10,Number(item?.price_inr||C.RINGTONE_OFFER_PRICE_INR||10));const j=await api('create-payment',{kind:'ringtone',item_id:id,amount});pending.order_id=j.order_id;location.href=j.payment_link;toast('Opening Razorpay. Save Order ID '+j.order_id)}catch(e){toast(e.message)}}
function musicLibrary(){return `<section class="hero"><h1>🎧 RacharlaGPT Music Library</h1><p>Your own/generated tracks. Admin publishing is handled in Supabase; customer playback remains separate from the ringtone catalog.</p></section><div class="card"><button class="btn" onclick="loadMusic()">Load Library</button><div id="musicOut" class="grid" style="margin-top:15px"></div></div>`}async function loadMusic(){if(!sb)return toast('Configure Supabase first');const {data,error}=await sb.from('music_library').select('*').eq('published',true).order('created_at',{ascending:false});if(error)return toast(error.message);$('#musicOut').innerHTML=(data||[]).map(x=>`<div class="card"><h3>${esc(x.title)}</h3><audio class="audio" controls src="${esc(x.preview_url||x.audio_url||'')}"></audio><p>${share('Listen on NavaBharat AI')}</p></div>`).join('')||'<div class="notice">No published tracks yet.</div>'}
async function adminTestProvider(provider){try{const token=sessionStorage.getItem('nava_admin_token')||'';if(!token)return toast('Unlock Admin first.');const r=await fetch(C.SUPABASE_URL+'/functions/v1/generate-media',{method:'POST',headers:{'Content-Type':'application/json','apikey':C.SUPABASE_ANON_KEY,'x-admin-token':token},body:JSON.stringify({kind:'song',lyrics:'ఆకాశం అంచున నా కల నిలిచింది\nనవ భారత గీతం నాలో మోగింది',language:'Telugu',style:'Tollywood Mass Folk / High Beat',duration:15,vocal_type:'Solo Male Vocalist',admin_test:true,test_provider:provider})});const j=await r.json();if(!r.ok)throw Error(j.error||'Provider test failed');const panel=$('#adminStatus');if(panel)panel.innerHTML=`<div class="notice">${esc(provider)} test succeeded. <audio class="audio" controls src="${esc(j.preview_url)}"></audio></div>`}catch(e){const panel=$('#adminStatus');if(panel)panel.innerHTML='<div class="notice">Provider test failed: '+esc(e.message)+'</div>'}}
function admin(){return `<section class="hero"><h1>🔐 Admin Studio</h1><p>Private management for your own RacharlaGPT Music tracks and your authorized ringtone catalog. Nothing here exposes provider keys.</p></section><div class="card"><h3>Admin access</h3><input id="adminToken" class="field" type="password" placeholder="Admin API token"><button class="btn" onclick="adminLogin()">Unlock Admin</button><div id="adminStatus" class="muted" style="margin-top:8px"></div><div class="row" style="margin-top:10px"><button class="btn secondary" onclick="adminTestProvider('acestep')">Test ACE-Step</button><button class="btn secondary" onclick="adminTestProvider('gemini')">Test Gemini Lyria</button><button class="btn secondary" onclick="adminTestProvider('apiframe')">Test APIFrame</button></div></div><div id="adminPanel" class="hidden"><div class="grid"><div class="card"><h3>🎧 Upload RacharlaGPT Music</h3><input id="musicFile" class="field" type="file" accept="audio/*"><input id="musicTitle" class="field" placeholder="Track title"><input id="musicLang" class="field" placeholder="Language"><input id="musicGenre" class="field" placeholder="Genre"><button class="btn" onclick="adminUploadMusic()">Upload & Publish</button></div><div class="card"><h3>🎵 Upload Ringtone</h3><input id="rtFile" class="field" type="file" accept="audio/*"><input id="rtTitle" class="field" placeholder="Ringtone title"><input id="rtMovie" class="field" placeholder="Movie / source name (optional)"><input id="rtArtist" class="field" placeholder="Artist / creator (optional)"><input id="rtLang" class="field" placeholder="Language"><input id="rtCategory" class="field" placeholder="Category e.g. Devotional / Folk"><input id="rtRegular" class="field" type="number" min="10" value="20" placeholder="Actual price ₹20+"><input id="rtPrice" class="field" type="number" min="10" value="10" placeholder="Offer price ₹10+"><input id="rtLicense" class="field" placeholder="License / permission reference"><label class="check"><input id="rtRights" type="checkbox"> I confirm I have redistribution rights for this upload</label><button class="btn" onclick="adminUploadRingtone()">Upload Ringtone</button></div><div class="card"><h3>🔄 Authorized Catalog</h3><p class="muted">Imports only sources whose license is recorded in Supabase. It does not scrape commercial movie sites.</p><button class="btn" onclick="refreshCatalog()">Refresh / Load Latest Authorized</button></div><div class="card"><h3>🗑️ Manage</h3><button class="btn secondary" onclick="adminLoadItems()">Load My Uploaded Items</button><div id="adminItems" style="margin-top:12px"></div></div></div></div>`}
function adminHeaders(){const t=sessionStorage.getItem('nava_admin_token')||$('#adminToken')?.value.trim();if(!t)throw Error('Enter the admin token');return {'x-admin-token':t}}
function adminLogin(){const t=$('#adminToken').value.trim();if(!t)return toast('Enter the admin token');sessionStorage.setItem('nava_admin_token',t);$('#adminPanel').classList.remove('hidden');$('#adminStatus').textContent='Admin controls unlocked for this browser session.';adminLoadItems().catch(e=>toast(e.message))}
function fileB64(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(file)})}
async function adminUploadMusic(){try{const f=$('#musicFile').files[0];if(!f)return toast('Choose an audio file');const body={type:'music',title:$('#musicTitle').value.trim()||f.name,language:$('#musicLang').value.trim(),genre:$('#musicGenre').value.trim(),data:await fileB64(f),mime:f.type};const j=await fetch(C.SUPABASE_URL+'/functions/v1/admin-upload',{method:'POST',headers:{'Content-Type':'application/json',...adminHeaders(),'apikey':C.SUPABASE_ANON_KEY},body:JSON.stringify(body)});const x=await j.json();if(!j.ok)throw Error(x.error||'Upload failed');toast('Music uploaded and published');adminLoadItems()}catch(e){toast(e.message)}}
async function adminUploadRingtone(){try{const f=$('#rtFile').files[0];if(!f)return toast('Choose an audio file');if(!$('#rtRights').checked)return toast('Confirm redistribution rights before uploading');const price=Math.max(10,Number($('#rtPrice').value||10));const body={type:'ringtone',title:$('#rtTitle').value.trim()||f.name,movie:$('#rtMovie').value.trim(),artist:$('#rtArtist').value.trim(),language:$('#rtLang').value.trim()||'English',category:$('#rtCategory').value.trim()||'Ringtone',regular_price_inr:Math.max(10,Number($('#rtRegular').value||20)),price_inr:price,license:$('#rtLicense').value.trim(),rights_confirmed:true,data:await fileB64(f),mime:f.type};const j=await fetch(C.SUPABASE_URL+'/functions/v1/admin-upload',{method:'POST',headers:{'Content-Type':'application/json',...adminHeaders(),'apikey':C.SUPABASE_ANON_KEY},body:JSON.stringify(body)});const x=await j.json();if(!j.ok)throw Error(x.error||'Upload failed');toast('Ringtone uploaded at ₹'+price);adminLoadItems()}catch(e){toast(e.message)}}
async function adminLoadItems(){try{const t=sessionStorage.getItem('nava_admin_token');if(!t)return;const j=await fetch(C.SUPABASE_URL+'/functions/v1/admin-list',{method:'POST',headers:{'Content-Type':'application/json',...adminHeaders(),'apikey':C.SUPABASE_ANON_KEY},body:'{}'});const x=await j.json();if(!j.ok)throw Error(x.error||'Admin list failed');$('#adminItems').innerHTML=(x.ringtones||[]).map(a=>`<div class="notice"><b>${esc(a.title)}</b> · ₹${a.price_inr} · ${esc(a.language||'')} <button class="btn small" onclick="adminDeleteRingtone('${a.id}')">Deactivate</button></div>`).join('')+(x.music||[]).map(a=>`<div class="notice"><b>🎧 ${esc(a.title)}</b> · ${esc(a.language||'')} <button class="btn small" onclick="adminDeleteMusic('${a.id}')">Unpublish</button></div>`).join('')||'No uploaded items.'}catch(e){toast(e.message)}}
async function adminDeleteRingtone(id){try{const r=await fetch(C.SUPABASE_URL+'/functions/v1/admin-delete-ringtone',{method:'POST',headers:{'Content-Type':'application/json',...adminHeaders(),'apikey':C.SUPABASE_ANON_KEY},body:JSON.stringify({id})});const j=await r.json();if(!r.ok)throw Error(j.error||'Delete failed');toast('Ringtone deactivated');adminLoadItems()}catch(e){toast(e.message)}}
async function adminDeleteMusic(id){try{const r=await fetch(C.SUPABASE_URL+'/functions/v1/admin-delete-music',{method:'POST',headers:{'Content-Type':'application/json',...adminHeaders(),'apikey':C.SUPABASE_ANON_KEY},body:JSON.stringify({id})});const j=await r.json();if(!r.ok)throw Error(j.error||'Unpublish failed');toast('Track unpublished');adminLoadItems()}catch(e){toast(e.message)}}
async function refreshCatalog(){try{const j=await fetch(C.SUPABASE_URL+'/functions/v1/refresh-catalog',{method:'POST',headers:{'Content-Type':'application/json',...adminHeaders(),'apikey':C.SUPABASE_ANON_KEY},body:'{}'}).then(async r=>{const j=await r.json();if(!r.ok)throw Error(j.error||'Catalog refresh failed');return j});toast('Catalog refreshed: '+(j.imported||0)+' authorized items')}catch(e){toast(e.message)}}
function currentAffairs(){return `<section class="hero"><h1>🗞️ Daily Current Affairs</h1><p>Fresh headlines and optional AI quiz in Indian languages.</p></section><div class="card"><div class="grid"><select id="caLang" class="field"><option>English</option><option>Telugu</option><option>Hindi</option><option>Tamil</option><option>Kannada</option><option>Malayalam</option></select><select id="caCat" class="field"><option>All</option><option>India</option><option>World</option><option>Business</option><option>Technology</option><option>Science</option><option>Sports</option><option>Education</option></select><select id="caCount" class="field"><option>5</option><option>10</option><option selected>12</option><option>15</option><option>20</option></select></div><button class="btn" onclick="loadCurrentAffairs()">📰 Load Today's Current Affairs</button><div id="caOut" style="margin-top:15px"></div></div>`}async function loadCurrentAffairs(){const lang=$('#caLang').value,cat=$('#caCat').value,count=Number($('#caCount').value);$('#caOut').innerHTML='<div class="notice">Fetching today\'s headlines…</div>';try{const j=await api('live-rss',{query:cat==='All'?'India':cat,language:lang,limit:Math.min(20,count*2)});let items=j.items||[];if(cat!=='All'){const terms={India:['india','indian'],World:['world','international','global'],Business:['business','economy','market','finance'],Technology:['technology','tech','ai','software'],Science:['science','space','research'],Sports:['sport','cricket','football','tennis'],Education:['education','school','university','exam']}[cat]||[];items=items.filter(x=>terms.some(t=>String(x.title).toLowerCase().includes(t)))}items=items.slice(0,count);window.__caItems=items;$('#caOut').innerHTML=items.map((x,i)=>`<div class="card"><h4>${i+1}. <a target="_blank" rel="noopener" href="${esc(x.link)}">${esc(x.title)}</a></h4><small>${esc(x.source||'Google News')} · ${esc(x.pubDate||'')}</small></div>`).join('')||'<div class="notice">No current-affairs items returned.</div>';if(items.length)$('#caOut').insertAdjacentHTML('beforeend','<button class="btn secondary" onclick="makeCurrentQuiz()">🤖 Create Daily Quiz</button>')}catch(e){$('#caOut').innerHTML='<div class="notice">'+esc(e.message)+'</div>'}}async function makeCurrentQuiz(){const items=window.__caItems||[];if(!items.length)return toast('Load headlines first.');try{const j=await api('ai-text',{type:'current_affairs',input:'Create 10 MCQs only from these headlines:\n'+items.map(x=>'- '+x.title).join('\n'),language:$('#caLang').value});$('#caOut').insertAdjacentHTML('beforeend','<pre class="output" style="margin-top:14px">'+esc(j.text)+'</pre>')}catch(e){toast(e.message)}}
function jobs(){return `<section class="hero"><h1>💼 Jobs & Competitive Exams</h1><p>Government jobs, recruitment notices and exam updates with AI summaries plus a live fallback.</p></section><div class="card"><select id="jobsCat" class="field"><option>All Government Jobs</option><option>Banking & Finance</option><option>SSC & Railways</option><option>UPSC & Civil Services</option><option>State Public Service Commissions</option></select><button class="btn" onclick="loadJobs()">🔍 Search Job & Exam Updates</button><div id="jobsOut" style="margin-top:15px"></div></div>`}async function loadJobs(){const cat=$('#jobsCat').value;$('#jobsOut').innerHTML='<div class="notice">Checking current updates…</div>';try{const j=await api('ai-text',{type:'jobs',input:cat,language:'English'});$('#jobsOut').innerHTML='<pre class="output">'+esc(j.text)+'</pre>'+share('NavaBharat AI jobs: '+cat)}catch(e){try{const r=await api('live-rss',{query:'India '+cat+' government jobs recruitment exam notification',language:'English',limit:15});$('#jobsOut').innerHTML=(r.items||[]).map(x=>`<div class="card"><h4><a target="_blank" rel="noopener" href="${esc(x.link)}">${esc(x.title)}</a></h4><small>${esc(x.source||'Google News')} · ${esc(x.pubDate||'')}</small></div>`).join('')||'<div class="notice">No job alerts found.</div>'}catch(e2){$('#jobsOut').innerHTML='<div class="notice">'+esc(e2.message)+'</div>'}}}
function creator(){return `<section class="hero"><h1>✨ Creator Studio</h1><p>Generate YouTube, Instagram, LinkedIn and X content with share-ready drafts.</p></section><div class="card"><input id="creatorTopic" class="field" placeholder="Content topic / idea"><select id="creatorPlatform" class="field"><option>YouTube Video Script & Metadata</option><option>Instagram Reel Caption & Hashtags</option><option>LinkedIn Thought Leadership Post</option><option>Twitter/X Thread</option></select><button class="btn" style="margin-top:12px" onclick="creatorGo()">✨ Generate Viral Content</button><div id="creatorOut" style="margin-top:18px"></div></div>`}async function creatorGo(){const topic=$('#creatorTopic').value.trim();if(!topic)return;$('#creatorOut').innerHTML='<div class="notice">Creating…</div>';try{const j=await api('ai-text',{type:'creator',input:topic+'\nPlatform: '+$('#creatorPlatform').value,language:'English'});$('#creatorOut').innerHTML=`<pre class="output">${esc(j.text)}</pre>${share('NavaBharat AI creator draft: '+topic)}`}catch(e){toast(e.message)}}
function design(){return `<section class="hero"><h1>🎨 NavaBharat Design Studio</h1><p>Create posters, 3D-style text graphics, thumbnails and stories. Free preview has branding; HD no-watermark export ₹9.</p></section><div class="card"><h3>🎨 Poster Design</h3><div class="grid"><div><input id="dTitle" class="field" placeholder="Main headline"><textarea id="dSub" class="field" placeholder="Supporting text"></textarea><input id="dFoot" class="field" value="NavaBharat AI"></div><div><select id="dFormat" class="field"><option>Instagram Square</option><option>Instagram Portrait</option><option>Instagram / WhatsApp Story</option><option>YouTube Thumbnail</option><option>LinkedIn Post</option><option>Quote Poster</option><option>Announcement</option></select><select id="dTheme" class="field"><option>Aurora</option><option>Sunset</option><option>Ocean</option><option>Emerald</option><option>Royal</option><option>Midnight</option></select><input id="dPhoto" class="field" type="file" accept="image/*"><button class="btn" onclick="makeDesign()">✨ Create Design</button></div></div><div id="designOut" style="margin-top:18px"></div></div><div class="card" style="margin-top:18px"><h3>🧊 3D Text Poster</h3><div class="grid"><input id="d3Text" class="field" maxlength="60" placeholder="Happy Sankranti / హ్యాపీ బర్త్‌డే"><input id="d3Sub" class="field" maxlength="90" placeholder="Small line"><select id="d3Fmt" class="field"><option>Instagram Square</option><option>Instagram Portrait</option><option>Instagram / WhatsApp Story</option><option>YouTube Thumbnail</option></select><select id="d3Style" class="field"><option>Chrome 3D</option><option>Neon 3D</option><option>Gold 3D</option><option>Glass 3D</option></select><select id="d3Bg" class="field"><option>Midnight</option><option>Aurora</option><option>Sunset</option><option>Ocean</option><option>Royal</option><option>Emerald</option></select><input id="d3Foot" class="field" value="NavaBharat AI"></div><button class="btn" onclick="make3DPoster()">🧊 Create 3D Poster</button><div id="design3dOut" style="margin-top:18px"></div></div>`}
function wrapCanvas(x,t,cx,cy,w,lh){let words=String(t||'').split(/\s+/),line='';for(const word of words){const test=line?line+' '+word:word;if(x.measureText(test).width>w){x.fillText(line,cx,cy);line=word;cy+=lh}else line=test}if(line)x.fillText(line,cx,cy)}
async function makeDesign(){const title=$('#dTitle').value.trim();if(!title)return toast('Enter a headline.');let photo=null;const f=$('#dPhoto')?.files?.[0];if(f){const r=new FileReader();photo=await new Promise(res=>{r.onload=()=>res(r.result);r.readAsDataURL(f)})}const p={type:'poster',title,subtitle:$('#dSub').value,footer:$('#dFoot').value,fmt:$('#dFormat').value,theme:$('#dTheme').value,photo};const preview=await renderPoster(p,true);localStorage.setItem('nava-design-pending',JSON.stringify(p));$('#designOut').innerHTML=`<img style="width:100%;border-radius:18px" src="${preview}"><div class="row"><a class="btn" download="navabharat-design-preview.jpg" href="${preview}">⬇ Download Preview</a><button class="btn secondary" onclick="shareDesign()">📤 Share</button><button class="btn" onclick="payDesignHD()">💎 HD ₹9</button></div>`}
async function renderPoster(p,watermark){const c=document.createElement('canvas');const sizes={'Instagram Square':[1080,1080],'Instagram Portrait':[1080,1350],'Instagram / WhatsApp Story':[1080,1920],'YouTube Thumbnail':[1280,720],'LinkedIn Post':[1200,627],'Quote Poster':[1080,1350],'Announcement':[1080,1080]};[c.width,c.height]=sizes[p.fmt]||[1080,1080];const x=c.getContext('2d');const g=x.createLinearGradient(0,0,c.width,c.height);g.addColorStop(0,'#0ea5e9');g.addColorStop(.5,'#7c3aed');g.addColorStop(1,'#ec4899');x.fillStyle=g;x.fillRect(0,0,c.width,c.height);if(p.photo){const img=new Image();img.src=p.photo;await new Promise(r=>img.onload=r);const sc=Math.max(.78*c.width/img.width,.35*c.height/img.height);x.globalAlpha=.42;x.drawImage(img,(c.width-img.width*sc)/2,.08*c.height,img.width*sc,img.height*sc);x.globalAlpha=1}x.fillStyle='rgba(10,5,25,.4)';x.fillRect(.055*c.width,.055*c.height,.89*c.width,.89*c.height);x.fillStyle='#fff';x.textAlign='center';x.font='900 '+Math.max(52,c.width/15)+'px Arial';wrapCanvas(x,p.title,c.width/2,c.height*.43,c.width*.8,Math.max(64,c.width/14));x.font=Math.max(26,c.width/34)+'px Arial';wrapCanvas(x,p.subtitle,c.width/2,c.height*.62,c.width*.78,Math.max(36,c.width/27));x.font='700 '+Math.max(20,c.width/55)+'px Arial';x.fillStyle='#ffd166';x.fillText(p.footer,c.width/2,c.height*.9);if(watermark){x.save();x.globalAlpha=.5;x.fillStyle='#fff';x.font='700 '+Math.max(22,c.width/55)+'px Arial';x.rotate(-Math.PI/8);for(let y=-c.height;y<c.height*2;y+=120)x.fillText('NavaBharat AI PREVIEW',0,y);x.restore()}return c.toDataURL('image/jpeg',.88)}
async function make3DPoster(){const p={type:'3d',title:$('#d3Text').value.trim(),subtitle:$('#d3Sub').value,fmt:$('#d3Fmt').value,style:$('#d3Style').value,bg:$('#d3Bg').value,footer:$('#d3Foot').value};if(!p.title)return toast('Type some text first.');const url=await render3D(p,true);localStorage.setItem('nava-design-pending',JSON.stringify(p));$('#design3dOut').innerHTML=`<img style="width:100%;border-radius:18px" src="${url}"><div class="row"><a class="btn" download="navabharat-3d-preview.png" href="${url}">⬇ Download Preview</a><button class="btn secondary" onclick="shareDesign()">📤 Share</button><button class="btn" onclick="payDesignHD()">💎 HD ₹9</button></div>`}
async function render3D(p,watermark){const c=document.createElement('canvas');const sizes={'Instagram Square':[1080,1080],'Instagram Portrait':[1080,1350],'Instagram / WhatsApp Story':[1080,1920],'YouTube Thumbnail':[1280,720]};[c.width,c.height]=sizes[p.fmt]||[1080,1080];const x=c.getContext('2d');const bg={Midnight:['#0f172a','#4f46e5'],Aurora:['#0ea5e9','#ec4899'],Sunset:['#fb923c','#a855f7'],Ocean:['#0891b2','#4f46e5'],Royal:['#4f46e5','#ec4899'],Emerald:['#059669','#22d3ee']}[p.bg]||['#0f172a','#4f46e5'];const g=x.createLinearGradient(0,0,c.width,c.height);g.addColorStop(0,bg[0]);g.addColorStop(1,bg[1]);x.fillStyle=g;x.fillRect(0,0,c.width,c.height);x.textAlign='center';x.font='900 '+Math.max(70,c.width/10)+'px Arial';for(let i=10;i>=1;i--){x.fillStyle='rgba(0,0,0,'+(0.035*i)+')';x.fillText(p.title,c.width/2+i*10,c.height*.52+i*10)}x.fillStyle='#fff';x.fillText(p.title,c.width/2,c.height*.52);x.font='700 '+Math.max(25,c.width/35)+'px Arial';x.fillStyle='#ffd166';x.fillText(p.subtitle,c.width/2,c.height*.68);x.font='600 '+Math.max(18,c.width/55)+'px Arial';x.fillText(p.footer,c.width/2,c.height*.9);if(watermark){x.save();x.globalAlpha=.5;x.fillStyle='#fff';x.font='700 '+Math.max(22,c.width/55)+'px Arial';x.rotate(-Math.PI/8);for(let y=-c.height;y<c.height*2;y+=120)x.fillText('NavaBharat AI PREVIEW',0,y);x.restore()}return c.toDataURL('image/png')}
async function payDesignHD(){const p=JSON.parse(localStorage.getItem('nava-design-pending')||'null');if(!p)return toast('Create a design first.');try{const j=await api('create-payment',{kind:'design',amount:9,customer:{design:{type:p.type,title:p.title}}});pending.order_id=j.order_id;pending.kind='design';location.href=j.payment_link}catch(e){toast(e.message)}}async function downloadPaidDesign(){const p=JSON.parse(localStorage.getItem('nava-design-pending')||'null');if(!p?.type)return toast('Design data is not available. Create it again.');const url=p.type==='3d'?await render3D(p,false):await renderPoster(p,false);const a=document.createElement('a');a.href=url;a.download=p.type==='3d'?'navabharat-3d-hd.png':'navabharat-design-hd.jpg';a.click();localStorage.removeItem('nava-design-pending');toast('HD no-watermark export unlocked.')}function shareDesign(){const p=JSON.parse(localStorage.getItem('nava-design-pending')||'null');if(navigator.share&&p){const run=async()=>{const url=p.type==='3d'?await render3D(p,true):await renderPoster(p,true);const b=await fetch(url).then(r=>r.blob());return navigator.share({title:'NavaBharat AI Design',files:[new File([b],'navabharat-design.png',{type:b.type})]})};run().catch(()=>{})}else toast('Use the download button and your phone share sheet.')}
function video(){return `<section class="hero"><h1>🎬 Video Studio & Audio Extractor</h1><p>Extract MP3 audio and render vertical 1080×1920 reels directly in the browser using FFmpeg WebAssembly. Files stay local.</p></section><div class="grid"><div class="card"><h3>🎵 Extract MP3</h3><input id="videoFile" class="field" type="file" accept="video/*"><button class="btn" style="margin-top:10px" onclick="extractAudio()">⚡ Extract MP3</button><div id="videoOut"></div></div><div class="card"><h3>🎞️ Build Reel Video</h3><input id="reelImgs" class="field" type="file" accept="image/*" multiple><input id="reelMusic" class="field" type="file" accept="audio/*"><button class="btn" onclick="buildReel()">🎞️ Render Vertical Reel</button><div id="reelOut" style="margin-top:12px"></div></div></div>`}
let ffmpegInstance=null;async function getFFmpeg(){if(ffmpegInstance)return ffmpegInstance;if(!window.FFmpegWASM){await new Promise((res,rej)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/@ffmpeg/ffmpeg@0.12.10/dist/umd/ffmpeg.js';s.onload=res;s.onerror=rej;document.head.appendChild(s)})}const {FFmpeg}=window.FFmpegWASM;const f=new FFmpeg();const base='https://cdn.jsdelivr.net/npm/@ffmpeg/core@0.12.6/dist/umd';await f.load({coreURL:base+'/ffmpeg-core.js',wasmURL:base+'/ffmpeg-core.wasm'});ffmpegInstance=f;return f}
async function extractAudio(){const file=$('#videoFile')?.files?.[0];if(!file)return toast('Upload a video first.');try{const f=await getFFmpeg();await f.writeFile('input',new Uint8Array(await file.arrayBuffer()));await f.exec(['-i','input','-vn','-codec:a','libmp3lame','-b:a','192k','output.mp3']);const data=await f.readFile('output.mp3');const blob=new Blob([data.buffer],{type:'audio/mpeg'}),url=URL.createObjectURL(blob);$('#videoOut').innerHTML=`<div class="notice">Audio extracted successfully.</div><audio class="audio" controls src="${url}"></audio><br><a class="btn" download="${esc(file.name.replace(/\.[^.]+$/,'')+'_audio.mp3')}" href="${url}">⬇ Download MP3</a>`}catch(e){$('#videoOut').innerHTML='<div class="notice">Extraction error: '+esc(e.message)+'</div>'}}
async function buildReel(){const imgs=[...($('#reelImgs')?.files||[])],music=$('#reelMusic')?.files?.[0];if(!imgs.length)return toast('Upload at least one image slide.');try{const f=await getFFmpeg();for(let i=0;i<imgs.length;i++)await f.writeFile('img'+i+'.jpg',new Uint8Array(await imgs[i].arrayBuffer()));if(music)await f.writeFile('music',new Uint8Array(await music.arrayBuffer()));let list='';for(let i=0;i<imgs.length;i++)list+="file 'img"+i+".jpg'\nduration 3\n";await f.writeFile('slides.txt',new TextEncoder().encode(list));const args=['-f','concat','-safe','0','-i','slides.txt'];if(music)args.push('-i','music');args.push('-vf','scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2','-r','30','-pix_fmt','yuv420p');if(music)args.push('-shortest');args.push('-c:v','libx264','-c:a','aac','reel.mp4');await f.exec(args);const data=await f.readFile('reel.mp4');const url=URL.createObjectURL(new Blob([data.buffer],{type:'video/mp4'}));$('#reelOut').innerHTML='<video class="audio" controls src="'+url+'"></video><br><a class="btn" download="navabharat_reel.mp4" href="'+url+'">⬇ Download Reel MP4</a>'}catch(e){$('#reelOut').innerHTML='<div class="notice">Reel error: '+esc(e.message)+'</div>'}}
function premium(){return `<section class="hero"><h1>💎 Premium & Support</h1><p>Secure Razorpay support, personalised song requests and order recovery — no customer login required.</p></section><div class="grid"><div class="card"><h3>❤️ Support RacharlaGPT</h3><p class="muted">Tip the project to help cover free AI/API/hosting costs.</p><div class="row">${[19,49,99,199].map(x=>`<button class="btn" onclick="tip(${x})">₹${x}</button>`).join('')}</div></div><div class="card"><h3>🎁 Personalised Song</h3><input id="giftName" class="field" placeholder="Name"><input id="giftWa" class="field" placeholder="WhatsApp number"><textarea id="giftMsg" class="field" placeholder="Occasion and message"></textarea><button class="btn" onclick="giftPay()">Continue to Razorpay</button></div><div class="card"><h3>🔎 Recover Order</h3><input id="recover" class="field" placeholder="Order ID"><button class="btn" style="margin-top:10px" onclick="recover()">Check Status</button><div id="recoverOut"></div></div></div><div class="notice" style="margin-top:18px">All payments are processed through Razorpay. Your card/UPI details never enter this website.</div>`}async function tip(a){try{const j=await api('create-payment',{kind:'tip',amount:a});pending.order_id=j.order_id;location.href=j.payment_link;toast('Opening Razorpay. Order '+j.order_id)}catch(e){toast(e.message)}}async function giftPay(){const name=$('#giftName').value.trim(),wa=$('#giftWa').value.trim(),msg=$('#giftMsg').value.trim();if(!name||!wa)return toast('Name and WhatsApp are required.');try{const j=await api('create-payment',{kind:'gift',amount:499,customer:{name,whatsapp:wa,message:msg}});location.href=j.payment_link;toast('Opening Razorpay. Personalised order created.')}catch(e){toast(e.message)}}async function recover(){try{const j=await api('order-status',{order_id:$('#recover').value.trim()});$('#recoverOut').innerHTML=`<div class="notice">${esc(j.message||'')}<br>${esc(j.order_id||'')}</div>`}catch(e){toast(e.message)}}
function about(){return `<section class="hero"><h1>ℹ️ About NavaBharat AI</h1><p>NavaBharat AI is a product of RacharlaGPT, created to bring practical AI tools, music creation, design, search and creator utilities together in a fast web app.</p></section><div class="card" style="margin-top:18px"><h3>Brand & Developer</h3><p class="muted">Designed & developed by <b>Saikrishna Racharla</b>.</p><p><a href="https://youtube.com/@racharlagpt" target="_blank">youtube.com/@racharlagpt</a></p><p>Karimnagar, Telangana, India</p></div>`}function privacy(){return `<section class="hero"><h1>🔒 Privacy</h1><p>We use Supabase for application data, Razorpay for payments and analytics/advertising services where enabled. Payment credentials are handled by Razorpay. API provider secrets are kept server-side in Supabase Edge Functions.</p></section><div class="card" style="margin-top:18px"><h3>Data principles</h3><p class="muted">No customer account is required for small purchases. Order IDs are used for recovery. Generated media may be retained according to the service's storage/cleanup policy. Do not upload sensitive personal information.</p></div>`}function contact(){return `<section class="hero"><h1>✉️ Contact</h1><p>For support, copyright/licensing questions, paid-order issues or business enquiries.</p></section><div class="card" style="margin-top:18px"><p>Email: <a href="mailto:${C.CONTACT_EMAIL}">${C.CONTACT_EMAIL}</a></p><p>Karimnagar, Telangana, India</p><p>YouTube: <a href="${C.CHANNEL_URL}" target="_blank">@racharlagpt</a></p></div>`}
function render(){const map={home,solve,musicGenerator,'ringtone-generator':ringtoneGenerator,'ringtone-library':ringtoneLibrary,search,science,translator,live,'current-affairs':currentAffairs,jobs,'music-library':musicLibrary,admin,video,creator,design,premium,about,privacy,contact};const f=map[current]||home;const r=f();if(r instanceof Promise)r.then(x=>$('#app').innerHTML='<div class="content">'+x+'</div>').catch(e=>$('#app').innerHTML='<div class="content"><div class="notice">Unable to render this page: '+esc(e.message)+'</div></div>');else $('#app').innerHTML='<div class="content">'+r+'</div>'}window.go=go;window.runAI=runAI;window.writeLyrics=writeLyrics;window.generateMedia=generateMedia;window.writeRingtoneIdea=writeRingtoneIdea;window.payAsset=payAsset;window.verifyOrder=verifyOrder;window.setRT=setRT;window.filterRT=filterRT;window.previewRT=previewRT;window.buyRT=buyRT;window.loadMusic=loadMusic;window.creatorGo=creatorGo;window.makeDesign=makeDesign;window.extractAudio=extractAudio;window.buildReel=buildReel;window.make3DPoster=make3DPoster;window.payDesignHD=payDesignHD;window.downloadPaidDesign=downloadPaidDesign;window.loadLiveRSS=loadLiveRSS;window.loadCurrentAffairs=loadCurrentAffairs;window.makeCurrentQuiz=makeCurrentQuiz;window.loadJobs=loadJobs;window.adminTestProvider=adminTestProvider;window.makeSearchImage=makeSearchImage;window.tip=tip;window.giftPay=giftPay;window.recover=recover;async function handlePaymentReturn(){const q=new URLSearchParams(location.search);const oid=q.get('order_id');if(q.get('payment')!=='done'||!oid)return;try{const j=await api('verify-payment',{order_id:oid});if(j.paid){toast('Payment confirmed: '+oid);if(['song','ringtone'].includes(j.kind||'')){const d=await api('create-download',{order_id:oid});location.href=d.download_url;return}if(j.kind==='design'){downloadPaidDesign();return}}else toast('Payment is still pending. Use Premium → Recover Order with '+oid)}catch(e){toast('Payment return: '+e.message)}}
const p=new URLSearchParams(location.search).get('page');go(p||'home');handlePaymentReturn();fetch('/version.json?ts='+Date.now()).then(r=>r.json()).then(v=>{if(v.version!==C.APP_VERSION){$('#updateBar').classList.remove('hidden');$('#refreshBtn').onclick=()=>location.reload(true)}}).catch(()=>{});
